export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import bcrypt from 'bcryptjs'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { db, setCurrentUserId } from '@/lib/db'
import { rateLimit, getClientIdentifier } from '@/lib/security/rateLimit'
import { sendTemplatedEmail } from '@/lib/email-templates'

// AUTO-GENERATED by api-row-sweep --apply — column types from migrations/*.sql + name heuristics.
// pg returns bigint/numeric as string, timestamptz as Date; nullable columns carry `| null`; REVIEW.
interface UserRow {
  password_hash: string
}

const updateSchema = z.object({
  currentPassword: z.string().min(1, 'Current password is required'),
  password: z.string().min(8, 'New password must be at least 8 characters'),
})

export async function POST(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const userId = session.user.id
    setCurrentUserId(userId)

    const body: unknown = await req.json().catch(() => ({}))
    const parsed = updateSchema.safeParse(body)
    if (!parsed.success) {
      return NextResponse.json({ error: parsed.error.issues[0]?.message ?? 'Invalid input' }, { status: 400 })
    }

    const identifier = `${userId}:${getClientIdentifier(req)}`
    const { allowed } = await rateLimit(`update-password:${identifier}`, 10, 15 * 60 * 1000)
    if (!allowed) {
      return NextResponse.json({ error: 'Too many requests. Please try again later.' }, { status: 429 })
    }

    // Verify current password
    const { rows: userRows } = await db.query<UserRow>(
      'SELECT password_hash FROM users WHERE id = $1',
      [userId]
    )
    if (userRows.length === 0) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    const currentValid = await bcrypt.compare(parsed.data.currentPassword, userRows[0].password_hash)
    if (!currentValid) {
      return NextResponse.json({ error: 'Current password is incorrect' }, { status: 400 })
    }

    const passwordHash = await bcrypt.hash(parsed.data.password, 12)
    const changed = await db.transaction(async (client) => {
      const result = await client.query<{ id: string }>(
        `UPDATE users SET password_hash = $1, session_version = session_version + 1, updated_at = NOW()
         WHERE id = $2 AND password_hash = $3 RETURNING id`,
        [passwordHash, userId, userRows[0].password_hash],
      )
      if (result.rows.length === 0) return false
      await client.query<never>(
        'UPDATE password_reset_tokens SET used_at = NOW() WHERE user_id = $1 AND used_at IS NULL',
        [userId],
      )
      return true
    })
    if (!changed) {
      return NextResponse.json({ error: 'Your password changed during this request. Sign in again before retrying.' }, { status: 409 })
    }

    const notification = session.user.email ? await sendTemplatedEmail('passwordChanged', {
      to: session.user.email, name: session.user.name || '',
    }).catch(() => ({ success: false })) : { success: false }
    return NextResponse.json({
      success: true,
      confirmationEmailSent: notification.success,
      sessionsRevoked: true,
      user: { id: userId, email: session.user.email, name: session.user.name },
    })
  } catch (err) {
    logger.error('[update-password] Error:', { error: err })
    return NextResponse.json({ error: 'Failed to update password' }, { status: 500 })
  }
}
